import {evidenceKindLabel} from './evidence-kind.mjs';
import {canonicalReportUrl} from './intelligence-data.mjs';
import {publisherPreview} from './publisher-preview.mjs';
import {oilMechanisms} from './situation-data.mjs';
import {reportContextLabel} from './reporting-view.mjs';

const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const validDate=value=>typeof value==='string'&&Number.isFinite(Date.parse(value));
const date=value=>validDate(value)?new Date(value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Unknown';
const time=value=>validDate(value)?new Date(value).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC':'';
const clock=(value,precision)=>validDate(value)?date(value)+(precision==='day'||/^\d{4}-\d{2}-\d{2}$/.test(value)?' · date only':' · '+time(value)):'Not established';
export function safeSourceUrl(value){return canonicalReportUrl(value);}
export function reportClockRows(report,source={}){
 const retained=report.retainedFromHistory||report.collectionRetired||report.retainedForReading;
 return [
  {label:'Event',value:report.eventDate,precision:report.eventPrecision||'day',note:report.eventDate?'Reported event date; event time may be unknown.':'No event date established. Publication is not substituted.'},
  {label:'Publication',value:report.publishedAt||report.publishedDate,precision:report.publicationPrecision,note:'The publisher’s date, when supplied.'},
  {label:'Discovery',value:report.discoveredAt,precision:report.discoveryPrecision,note:'Index discovery is not a publication or event date.'},
  retained?{label:'Record retrieval',value:report.retrievedAt||report.lastSeenAt,precision:'timestamp',note:'Last recorded retrieval of this record; later source checks do not update this clock.'}:{label:'Source retrieval',value:source.lastSuccessAt||source.retrievedAt||report.retrievedAt,precision:'timestamp',note:'Last successful source retrieval, not the most recent attempt.'},
 ];
}
export function reportInspectorMarkup(report,{source={},saved=false,note=''}={}){
 const url=safeSourceUrl(report.url),preview=publisherPreview(report.summary),rows=reportClockRows(report,source),channels=oilMechanisms(report).slice(0,3);
 const kind=evidenceKindLabel(report),discovery=Boolean(report.sourceId?.startsWith('gdelt')||report.contentAccess==='discovery-metadata');
 const region=(report.theaters||[]).map(reportContextLabel).join(' / ')||'Regional context';
 return `<div class="report-record"><div class="record-eyebrow"><span>${escape(kind)}${discovery?' · Discovery metadata':''}</span><span>${escape(region)}</span></div><h2 class="record-title">${escape(report.title)}</h2><p class="record-source">${escape(report.source||'Source not supplied')} · ${report.publishedAt||report.publishedDate?'Published '+escape(date(report.publishedAt||report.publishedDate)):report.discoveredAt?'Discovered '+escape(date(report.discoveredAt))+' · publication unknown':'Publication date unknown'}</p><div class="record-primary-actions">${url?`<a class="primary-link" href="${escape(url)}" target="_blank" rel="noopener noreferrer">Read original source <span aria-hidden="true">↗</span></a>`:'<span class="evidence-watch">Original URL unavailable</span>'}<button id="detail-save" class="text-button">${saved?'Saved ✓':'Save report'}</button></div>
 <div class="record-tabs" role="tablist" aria-label="Inspect this report"><button id="record-tab-claim" role="tab" aria-controls="record-claim" aria-selected="true" data-inspector-tab="claim">01 Claim</button><button id="record-tab-confirm" role="tab" aria-controls="record-confirm" aria-selected="false" tabindex="-1" data-inspector-tab="confirm">02 Confirm</button><button id="record-tab-oil" role="tab" aria-controls="record-oil" aria-selected="false" tabindex="-1" data-inspector-tab="oil">03 Oil connection</button></div>
 <section id="record-claim" class="record-panel" role="tabpanel" aria-labelledby="record-tab-claim"><span class="record-section-label">WHAT THE SOURCE SAYS</span>${preview?`<p class="record-preview">${escape(preview)}</p><p class="record-caption">${report.contentAccess==='discovery-metadata'?'Discovery metadata':report.type==='Independent energy analysis'?'Public preview':'Publisher feed summary'} · the full article is not imported</p>`:'<p class="record-preview">Only the original headline and link are available in this record. Open the publisher’s account before assessing the claim.</p>'}<div class="record-clock-summary"><div><span>Publication</span><strong>${escape(clock(report.publishedAt||report.publishedDate,report.publicationPrecision))}</strong></div><div><span>Event date</span><strong>${report.eventDate?escape(clock(report.eventDate,'day')):'Not established'}</strong></div></div><p class="record-limit">${discovery?'A discovered link does not verify the underlying claim. ':''}Theatre and actor tags describe text relevance. They do not verify a location or responsibility.</p>${report.retainedFromHistory?'<p class="record-limit">Retained from the archive; absent from the current source snapshot. This does not establish that the situation has ended.</p>':''}${report.retainedForReading?'<p class="record-limit">Held for reading until you accept refreshed results.</p>':''}<details class="record-personal"><summary>Your note <span>Stored only on this device</span></summary><label class="note-label" for="analyst-note">Separate sourced facts from your assessment</label><textarea id="analyst-note" placeholder="Your assessment and the evidence it still needs…">${escape(note)}</textarea><button id="save-note" class="text-button">Save note</button></details></section>
 <section id="record-confirm" class="record-panel" role="tabpanel" aria-labelledby="record-tab-confirm" hidden><span class="record-section-label">DATES &amp; EVIDENCE</span><dl class="record-clocks">${rows.map(row=>`<div><dt>${escape(row.label)}</dt><dd>${escape(clock(row.value,row.precision))}<small>${escape(row.note)}</small></dd></div>`).join('')}</dl><h3>What would strengthen this account</h3><p>${escape(report.watch||'A dated operator or official record identifying the affected route or facility, the duration, and measured changes in transit or loadings. Check subsequent corrections and independently sourced accounts.')}</p><button class="text-button" id="inspect-official-records">Check official evidence →</button><details class="record-provenance"><summary>Source &amp; archive provenance</summary><p>Source state: ${escape(source.label||source.status||'Not supplied')}. A successful retrieval is not independent verification.</p>${report.retainedFromHistory||report.collectionRetired||report.retainedForReading?`<p>Latest successful source check: ${escape(clock(source.lastSuccessAt||source.retrievedAt))}. This does not update the archived record’s retrieval date.</p>`:''}${report.firstSeenAt?`<p>First retrieved by Passage: ${escape(clock(report.firstSeenAt))}</p>`:''}${report.lastSeenAt?`<p>Last present in a source: ${escape(clock(report.lastSeenAt))}</p>`:''}${report.attributionNote?`<p>${escape(report.attributionNote)}</p>`:''}<p>Matching headlines are grouped for reading only. They are not independent witnesses.</p></details></section>
 <section id="record-oil" class="record-panel" role="tabpanel" aria-labelledby="record-tab-oil" hidden><span class="record-section-label">POSSIBLE CONNECTION / NOT A MEASURED EFFECT</span>${channels.length?channels.map(channel=>`<div class="record-mechanism"><h3>${escape(channel.name)}</h3><p>${escape(channel.explanation)}</p></div>`).join(''):'<p>No direct oil-supply or transport mechanism is established by this headline.</p>'}<p class="record-limit">These are possible channels suggested by the available text. No physical loss, operating status or price causation is inferred.</p><button class="primary-link" id="inspect-report-system">Explore the oil connection →</button><p class="record-caption">The selected report stays attached. Brent and WTI keep their own observation dates.</p></section></div>`;
}
export function bindInspectorTabs(root){
 const tabs=[...root.querySelectorAll('[data-inspector-tab]')];
 const select=(tab,focus=false)=>{for(const item of tabs){const active=item===tab;item.setAttribute('aria-selected',String(active));item.tabIndex=active?0:-1;const panel=root.querySelector('#'+item.getAttribute('aria-controls'));if(panel)panel.hidden=!active;}if(focus)tab.focus({preventScroll:true});};
 for(const tab of tabs){tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',event=>{const index=tabs.indexOf(tab),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:event.key==='ArrowRight'?(index+1)%tabs.length:event.key==='ArrowLeft'?(index+tabs.length-1)%tabs.length:null;if(next===null)return;event.preventDefault();select(tabs[next],true);});}
}
